import React, { useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import NavBar from "../../../components/NavBar";
import SvgLeftArrow from "../../../assets/agentIcon/SvgLeftArrow";
import { Card } from "primereact/card";
import { useNavigate, useParams, useLocation } from "react-router-dom";
import { Button } from "primereact/button";
import DropdownField from "../../component/DropdwonField";
import InputTextField from "../../component/inputText";
import { Checkbox } from "primereact/checkbox";
import DatepickerField from "../../component/datePicker";
import { FileUpload } from "primereact/fileupload";
import SvgImageUpload from "../../../assets/icons/SvgImageUpload";

import SvgImageShow from "../../../assets/agentIcon/SvgHelp";
import "./index.scss";
import CustomToast from "../../../components/Toast";
import customHistory from "../../../routes/customHistory";
import { useDispatch, useSelector } from "react-redux";
import { useFormik } from "formik";
import { postSettlementClaimMiddleware } from "./Store/claimSettlementMiddleware";
import SvgUploadClose from "../../../assets/agentIcon/SvgUploadClose";

const initialValues = {
  settlementType: "",
  settlementAmount: "",
  settlementIssueDate: new Date(),
  settlementDate: new Date(),
  settlementDocument: null,
};

const SettlementDetails = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const toastRef = useRef(null);
  const dispatch = useDispatch();
  const params = useParams();
  const { id } = params;
  const [loading, setLoading] = useState(false);

  // Label = translated for UI; value = English for API (backend expects Cash, Card, Cheque)
  const items = [
    { label: t("settlementDetails.cash"), value: "Cash" },
    { label: t("settlementDetails.card"), value: "Card" },
    { label: t("settlementDetails.cheque"), value: "Cheque" },
  ];

  // Get claim ID from URL params or navigation state
  const claimId = id || location.state?.claimId || location.state?.id;

  // Get policy holder data from Redux
  const {
    policyHolderName: reduxPolicyHolderName,
    policyNumber: reduxPolicyNumber,
    claimNumber: reduxClaimNumber,
  } = useSelector(({ claimDetailsMainReducers }) => ({
    policyHolderName: claimDetailsMainReducers?.policyHolderName || "",
    policyNumber: claimDetailsMainReducers?.policyNumber || "",
    claimNumber: claimDetailsMainReducers?.claimNumber || "",
  }));

  // Try to get policy holder name from Redux first, then fallback
  const policyHolderName = reduxPolicyHolderName || t("common.loading");

  const claimNumber = reduxClaimNumber || t("common.loading");

  console.log("=== SETTLEMENT DETAILS PAGE DATA ===");
  console.log("URL Params:", params);
  console.log("Navigation State:", location.state);
  console.log("Claim ID:", claimId);
  console.log("=== REDUX POLICY HOLDER DATA ===");
  console.log("Redux Policy Holder Name:", reduxPolicyHolderName);
  console.log("Redux Policy Number:", reduxPolicyNumber);
  console.log("Redux Claim Number:", reduxClaimNumber);
  console.log("Final Policy Holder Name:", policyHolderName);
  console.log("Final Claim Number:", claimNumber);
  console.log("=== END REDUX POLICY HOLDER DATA ===");
  console.log("=== END SETTLEMENT DETAILS PAGE DATA ===");
  const handleEdit = () => {
    navigate("/agent/claimrequest/claimdetails");
  };
  const handleSubmit = async (values) => {
    if (!claimId) {
      console.error("No claim ID available for settlement");
      return;
    }

    setLoading(true);
    console.log("=== SUBMITTING SETTLEMENT ===");
    console.log("Claim ID:", claimId);
    console.log("Settlement Values:", values);
    console.log("=== END SUBMITTING SETTLEMENT ===");

    try {
      // Prepare settlement data for API
      const settlementData = {
        settlementType: values.settlementType,
        settlementAmount: values.settlementAmount,
        settlementIssueDate: values.settlementIssueDate.toISOString(),
        settlementDate: values.settlementDate.toISOString(),
        settlementDocument: values.settlementDocument,
      };

      const result = await dispatch(
        postSettlementClaimMiddleware({
          claimId: claimId,
          settlementData: settlementData,
        })
      );

      if (result.type.endsWith("/fulfilled")) {
        console.log("Settlement submitted successfully:", result.payload);
        toastRef.current.showToast();
        setTimeout(() => {
          navigate(`/agent/claimdetailedview/${claimId}`);
        }, 2000);
      } else {
        console.error("Settlement submission failed:", result.payload);
        // You can add error handling here
      }
    } catch (error) {
      console.error("Error submitting settlement:", error);
      // You can add error handling here
    } finally {
      setLoading(false);
    }
  };

  const fileUploadRef = useRef(null);
  const [uploadImage, setuploadImage] = useState(null);
  const handleUppendImg = (name, src) => {
    console.log(name, src, "find handleUppendImg");
    setuploadImage(src?.objectURL);
  };
  const handleCancelUplaoded = () => {
    setuploadImage(null);
    fileUploadRef.current.clear();
  };
  const [checked, setChecked] = useState(false);
  const handleBackNavigation = () => {
    customHistory.back();
  };
  const formik = useFormik({
    initialValues: initialValues,
    // validate: customValidation,
    // onSubmit: handleSubmit,
    onSubmit: (values) => {
      handleSubmit(values);
    },
  });
  return (
    <div>
      <CustomToast ref={toastRef} message={t("settlementDetails.claimSettledSuccess")} />
      <div className="claim__settlementdetails__container">
        <div className="claim__details__container__titles">{t("settlementDetails.clients")}</div>
        <div 
          className="claim__details__container__back__btn mt-3 cursor-pointer"
          onClick={handleBackNavigation}
        >
          <SvgLeftArrow />
          <div className="claim__details__container__back__btn__title">
            {policyHolderName} / {reduxClaimNumber ? t("settlementDetails.claimLabel", { claimNumber: reduxClaimNumber }) : t("common.loading")}
          </div>
        </div>
        <Card>
          <div className="claim__details__card__container__title">
            {t("settlementDetails.claimSettlement")}
          </div>
          <div className="grid mt-2">
            <div className="col-12 md:col-6 lg:col-6">
              <DropdownField
                label={t("settlementDetails.settlementType")}
                value={formik.values.settlementType}
                onChange={(e) =>
                  formik.setFieldValue("settlementType", e.value)
                }
                options={items}
                optionLabel="label"
                optionValue="value"
                placeholder={t("settlementDetails.select")}
              />
            </div>
            <div className="col-12 md:col-6 lg:col-6">
              <InputTextField
                label={t("settlementDetails.settlementAmount")}
                value={formik.values.settlementAmount}
                onChange={formik.handleChange("settlementAmount")}
              />
            </div>
          </div>

          <div className="grid mt-2">
            <div className="col-12 md:col-6 lg:col-6">
              <DatepickerField
                label={t("settlementDetails.issueDate")}
                value={formik.values.settlementIssueDate}
                onChange={(e) => {
                  formik.setFieldValue("settlementIssueDate", e.value);
                }}
                dateFormat="yy-mm-dd"
              />
            </div>
            <div className="col-12 md:col-6 lg:col-6">
              <DatepickerField
                label={t("settlementDetails.settleDate")}
                value={formik.values.settlementDate}
                onChange={(e) => {
                  formik.setFieldValue("settlementDate", e.value);
                }}
                dateFormat="yy-mm-dd"
              />
            </div>
          </div>

          <div className="col-12 mt-4 p-0">
            <div className="claim__request__upload__subtitle  mb-2">
              {t("settlementDetails.documents")}
            </div>

            <div className="upload__card__container mt-2">
              <div className="file_icon_selector">
                <FileUpload
                  ref={fileUploadRef}
                  url="./upload"
                  auto
                  customUpload
                  mode="basic"
                  name="demo"
                  accept=".png,.jpg,.jpeg"
                  uploadHandler={(e) => {
                    const file = e.files[0];
                    formik.setFieldValue("settlementDocument", file);
                    handleUppendImg(e.options.props.name, file, "the data");
                  }}
                />
                <div className="icon_click_option">
                  <SvgImageUpload />
                </div>
                <div className="upload__caption text-center">{t("settlementDetails.upload")}</div>
                <div className="upload__caption text-center">
                  {t("settlementDetails.uploadMaxSize")}
                </div>
              </div>
            </div>
            {uploadImage && (
              <div onClick={handleCancelUplaoded} className="mt-2">
                <SvgUploadClose />
              </div>
            )}
          </div>

          <div className="claimrequest__back__but">
            <Button
              onClick={handleBackNavigation}
              link
              className="claim__back__but"
            >
              {t("settlementDetails.back")}
            </Button>
            <Button
              onClick={formik.handleSubmit}
              className="claim__snd__but"
              disabled={loading}
              loading={loading}
            >
              {loading ? t("settlementDetails.submitting") : t("settlementDetails.submit")}
            </Button>
          </div>
        </Card>
      </div>
    </div>
  );
};

export default SettlementDetails;
