import React, { useEffect, useState, useRef } from "react";
import { useTranslation } from "react-i18next";
import "./index.scss";
import { BreadCrumb } from "primereact/breadcrumb";
import InputField from "../../../components/InputField";
import SvgDot from "../../../assets/icons/SvgDot";
import DropDowns from "../../../components/DropDowns";
import SvgDropdown from "../../../assets/icons/SvgDropdown";
import { Button } from "primereact/button";
import { useNavigate, useParams } from "react-router-dom";
import NavBar from "../../../components/NavBar";
import SvgBackicon from "../../../assets/icons/SvgBackicon";
import { Card } from "primereact/card";
import DatePicker from "../../../components/DatePicker";
import { Calendar } from "primereact/calendar";
import LabelWrapper from "../../../components/LabelWrapper";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import Productdata from "./mock";
import { Dropdown } from "primereact/dropdown";
import { useDispatch, useSelector } from "react-redux";
import {
  getDisbursementDetailsMiddleware,
} from "../store/paymentVocherMiddleware";
import CustomToast from "../../../components/Toast";
import disbursementService from "../../../services/disbursementService";

function Detailview() {
  const { t } = useTranslation();
  const { id } = useParams();
  const dispatch = useDispatch();
  const toastRef = useRef(null);
  const [selectedProducts, setSelectedProducts] = useState(null);
  const [actionToast, setActionToast] = useState(null);

  useEffect(() => {
    dispatch(getDisbursementDetailsMiddleware(id));
  }, [id, dispatch]);

  const { chequebooklist, disbursementDetails, loading } = useSelector(
    ({ paymentVoucherReducers }) => {
      return {
        loading: paymentVoucherReducers?.loading,
        chequebooklist: paymentVoucherReducers?.chequebooklist,
        disbursementDetails: paymentVoucherReducers?.disbursementDetails,
      };
    }
  );

  const Navigate = useNavigate();

  // Show toast when actionToast changes
  useEffect(() => {
    if (actionToast != null) {
      toastRef.current?.showToast();
    }
  }, [actionToast]);

  const items = [
    {
      label: t("paymentVoucher.title"),
      command: () => Navigate("/accounts/paymentvoucher/"),
    },
    {
      label: t("paymentVoucher.disbursementDetails"),
      to: "/accounts/paymentvoucher/detailview",
    },
  ];
  const statusBodyTemplate = (rowData) => {
    return (
      <div
        style={{
          backgroundColor: rowData.status !== "Pending" ? "#E2F6EF" : "#FFE5B4",
          color: rowData.status !== "Pending" ? "#29CE00" : "#FFA800",
        }}
        className="statuslable_container"
      >
        {rowData.status}
      </div>
    );
  };

  const template2 = {
    layout:
      "RowsPerPageDropdown  FirstPageLink PrevPageLink CurrentPageReport NextPageLink LastPageLink",
    RowsPerPageDropdown: (options) => {
      const dropdownOptions = [
        { label: 5, value: 5 },
        { label: 10, value: 10 },
        { label: 20, value: 20 },
        { label: 120, value: 120 },
      ];

      return (
        <React.Fragment>
          <span
            className="mx-1"
            style={{ color: "var(--text-color)", userSelect: "none" }}
          >
            {t("paymentVoucher.rowCount")}{" "}
          </span>
          <Dropdown
            value={options.value}
            className="pagedropdown_container"
            options={dropdownOptions}
            onChange={options.onChange}
          />
        </React.Fragment>
      );
    },
  };

  const headerStyle = {
    // width: '12rem',
    // backgroundColor: 'red',
    fontSize: 16,
    fontFamily: "Inter, sans-serif",
    fontWeight: 500,
    padding: 6,
    color: "#000",
    border: "none",
    paddingLeft: 0,
  };
  const status = [
    { name: "Active", code: "NY" },
    { name: "Deactive", code: "RM" },
  ];
  const item = [
    { name: "New York", code: "NY" },
    { name: "Rome", code: "RM" },
    { name: "London", code: "LDN" },
    { name: "Istanbul", code: "IST" },
    { name: "Paris", code: "PRS" },
  ];
  const home = { label: t("paymentVoucher.accounts") };
  const getStatusClassName = (status) => {
    return status === "Printed" ? "disabled-row" : "";
  };

  // Process cheque book data from API response
  const processedChequeBookData = React.useMemo(() => {
    if (!disbursementDetails?.invoiceList) {
      return [];
    }
    
    const chequeBooks = [];
    disbursementDetails.invoiceList.forEach((invoice) => {
      if (invoice.checkbooks && invoice.checkbooks.length > 0) {
        invoice.checkbooks.forEach((checkbook) => {
          chequeBooks.push({
            id: checkbook.checkbookId,
            VoucherNumber: checkbook.customerCode || "",
            TransactionNumber: checkbook.customerName || "",
            CustomerCode: checkbook.mainAccount || "",
            VoucheDate: checkbook.instrumentBookId || "",
            Amount: checkbook.instrumentNo || "",
            InstrumentDate: checkbook.instrumentDate || "",
            TotalAmount: checkbook.totaleAmount || "",
            status: checkbook.status || "",
            action: checkbook.checkbookId,
            rawData: checkbook, // Store raw data for API calls
          });
        });
      }
    });
    
    return chequeBooks;
  }, [disbursementDetails]);

  // Check if there are any items with "Pending" status
  const hasPendingItems = React.useMemo(() => {
    return processedChequeBookData.some((item) => item.status === "Pending");
  }, [processedChequeBookData]);

  // Handle approve action
  const handleApprove = async () => {
    if (!selectedProducts || !selectedProducts.rawData) {
      toastRef.current?.showToast("error", t("common.error"), t("paymentVoucher.noCheckbookSelected"));
      return;
    }

    const checkbookData = selectedProducts.rawData;
    const checkbookId = checkbookData.checkbookId;

    if (!checkbookId) {
      toastRef.current?.showToast("error", t("common.error"), t("paymentVoucher.invalidCheckbookData"));
      return;
    }

    if (checkbookData.status !== "Pending") {
      toastRef.current?.showToast("error", t("common.error"), t("paymentVoucher.onlyPendingCanBeApproved"));
      return;
    }

    try {
      // Update the checkbook status to "Approved"
      const result = await disbursementService.updateCheckbook(checkbookId, {
        status: "Approved",
      });

      if (result.success) {
        console.log("Checkbook approved successfully:", result.data);
        setActionToast("approved");
        // Clear selection
        setSelectedProducts(null);
        // Refetch the disbursement details to show updated status
        dispatch(getDisbursementDetailsMiddleware(id));
      } else {
        console.error("Failed to approve checkbook:", result.error);
        toastRef.current?.showToast("error", t("common.error"), result.error || t("paymentVoucher.failedToApproveCheckbook"));
      }
    } catch (error) {
      console.error("Error approving checkbook:", error);
      toastRef.current?.showToast("error", t("common.error"), error.message || t("paymentVoucher.failedToApproveCheckbook"));
    }
  };
  return (
    <div className="overall__detailview__container">
      <CustomToast
        ref={toastRef}
        message={actionToast === "approved" ? t("paymentVoucher.chequeBookApprovedSuccess") : `${actionToast} successfully`}
      />
      <div>
        <span onClick={() => Navigate(-1)}>
          <SvgBackicon />
        </span>

        <label className="label_header">{t("paymentVoucher.disbursementDetails")}</label>
        {loading && <span style={{ marginLeft: '10px', color: '#666' }}>{t("common.loading")}</span>}
      </div>
      <BreadCrumb
        model={items}
        home={home}
        className="breadcrumbs_container"
        separatorIcon={<SvgDot color={"#000"} />}
      />

      <Card className="cardstyle_container">
        <div class="grid">
          <div class="sm-col-12 col-12 md:col-3 lg-col-4">
            <div>
              <InputField
                classNames="field__container"
                label={t("paymentVoucher.departmentCode")}
                value={disbursementDetails?.departmentCode || ""}
                disabled={true}
              />
            </div>
          </div>
          <div class="sm-col-12 col-12 md:col-3 lg-col-4">
            <div>
              <InputField
                classNames="field__container"
                label={t("paymentVoucher.branchCode")}
                value={disbursementDetails?.branchCode || ""}
                disabled={true}
              />
            </div>
          </div>
          <div class="sm-col-12  md:col-3 lg-col-4">
            <div>
              <InputField
                classNames="field__container"
                label={t("paymentVoucher.payeeType")}
                value={disbursementDetails?.payeeType || ""}
                disabled={true}
              />
            </div>
          </div>
          <div class="sm-col-12 col-12 md:col-3 lg-col-4">
            <div>
              <InputField
                classNames="field__container"
                label={t("paymentVoucher.criteria")}
                value={disbursementDetails?.criteria || ""}
                disabled={true}
              />
            </div>
          </div>
        </div>

        <div class="grid">
          <div class="col-3 md:col-3 lg-col-3">
            <InputField
              classNames="field__container"
              label={t("paymentVoucher.customerCode")}
              value={disbursementDetails?.customerCode || ""}
              disabled={true}
            />
          </div>
          <div class="col-3 md:col-3 lg-col-3">
            <InputField
              classNames="field__container"
              label={t("paymentVoucher.transactionType")}
              placeholder={t("paymentVoucher.enter")}
              value={disbursementDetails?.transactionCode || ""}
              disabled={true}
            />
          </div>
          <div class="sm-col-12 col-12 md:col-6 lg-col-6">
            <InputField
              classNames="field__container"
              label={t("paymentVoucher.paymentDescription")}
              value={disbursementDetails?.transactionDescription || ""}
              disabled={true}
            />
          </div>
        </div>
        <div class="grid">
          <div class="sm-col-12  md:col-3 lg-col-4">
            <InputField
              classNames="field__container"
              label={t("paymentVoucher.paymentCurrency")}
              value={disbursementDetails?.instrumentCurrency || ""}
              disabled={true}
            />
          </div>
          <div class="sm-col-12  md:col-6 lg-col-6">
            <InputField
              classNames="field__container"
              label={t("paymentVoucher.paymentNotesOptional")}
              value={disbursementDetails?.remarks || ""}
              disabled={true}
            />
          </div>
        </div>
      </Card>

      <label className="headlist_lable">{t("paymentVoucher.chequeBookDetails")}</label>

      <div className="tablegap_container">
        <DataTable
          value={processedChequeBookData}
          tableStyle={{ minWidth: "50rem", color: "#1C2536" }}
          paginator
          rows={5}
          rowsPerPageOptions={[5, 10, 25, 50]}
          // paginatorTemplate="RowsPerPageDropdown  FirstPageLink PrevPageLink CurrentPageReport NextPageLink LastPageLink"
          currentPageReportTemplate="{first} - {last} of {totalRecords}"
          paginatorTemplate={template2}
          scrollable={true}
          scrollHeight="40vh"
          rowClassName={(rowData) => {
            const baseClass = getStatusClassName(rowData.status);
            // Add disabled class for non-Pending rows when checkboxes are shown
            if (hasPendingItems && rowData.status !== "Pending") {
              return baseClass ? `${baseClass} non-selectable-row` : "non-selectable-row";
            }
            return baseClass;
          }}
          selection={selectedProducts}
          onSelectionChange={(e) => {
            // Use e.value directly - PrimeReact passes the exact row object
            // Only allow selection of Pending items
            if (e.value && e.value.status === "Pending") {
              setSelectedProducts(e.value);
            } else {
              // Clear selection if clicking non-Pending item or deselecting
              setSelectedProducts(null);
            }
          }}
          selectionMode={hasPendingItems ? "checkbox" : undefined}
          dataKey="id"
        >
          {hasPendingItems && (
            <Column
              selectionMode="single"
              selectedItem
              headerStyle={{ width: "4rem", border: "0px solid #000" }}
              style={{ textAlign: "center" }}
            ></Column>
          )}
          <Column
            field="VoucherNumber"
            header={t("paymentVoucher.customerCode")}
            headerStyle={headerStyle}
            sortable
            className="fieldvalue_container"
          ></Column>
          <Column
            field="TransactionNumber"
            header={t("paymentVoucher.customerName")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="CustomerCode"
            header={t("paymentVoucher.mainAccount")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="VoucheDate"
            header={t("paymentVoucher.instrumentBookId")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="Amount"
            header={t("paymentVoucher.instrumentNo")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="InstrumentDate"
            header={t("paymentVoucher.instrumentDate")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="TotalAmount"
            header={t("paymentVoucher.totalAmount")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
          ></Column>
          <Column
            field="status"
            header={t("paymentVoucher.status")}
            headerStyle={headerStyle}
            className="fieldvalue_container"
            body={statusBodyTemplate}
          ></Column>
        </DataTable>
      </div>

      {hasPendingItems && (
        <div className="next_container">
          <Button
            className="submit_button p-0"
            label={t("paymentVoucher.approve")}
            onClick={handleApprove}
            disabled={!selectedProducts || selectedProducts.status !== "Pending"}
          />
        </div>
      )}

    </div>
  );
}

export default Detailview;
